tot=0; stmt=0
for f in files:
    try: src=open(f,encoding='utf-8').read()
    except: continue
    lines=src.splitlines(); tot+=len(lines)
    code=set()
    try:
        for tok in tokenize.generate_tokens(io.StringIO(src).readline):
            if tok.type in (tokenize.COMMENT, tokenize.NL, tokenize.NEWLINE, tokenize.INDENT, tokenize.DEDENT, tokenize.ENDMARKER): continue
            if tok.type==tokenize.STRING and tok.line.strip().startswith(('"""',"'''",'"',"'")) and tok.line.strip()==tok.string.split('\n')[0]: 
                continue
            for ln in range(tok.start[0], tok.end[0]+1): code.add(ln)
    except Exception as e: pass
    stmt+=len(code)
print(f"files={len(files)} lines={tot} statement-ish lines={stmt} share={stmt/tot:.0%}")
PY

