python3 -I - <<'PY'
import subprocess, ast, tokenize, io
files=subprocess.run(['git','ls-files','scripts/*.py','scripts/**/*.py','tools/*.py','schemas/*.py'],capture_output=True,text=True).stdout.split()
tot=0; stmt=0
for f in files:
    try: src=open(f,encoding='utf-8').read()
    except: continue
    lines=src.splitlines(); n=len(lines); tot+=n
    doc=set()
    try:
        tree=ast.parse(src)
        for node in ast.walk(tree):
            if isinstance(node,(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)) and node.body and isinstance(node.body[0],ast.Expr) and isinstance(getattr(node.body[0],'value',None),ast.Constant) and isinstance(node.body[0].value.value,str):
                for ln in range(node.body[0].lineno, node.body[0].end_lineno+1): doc.add(ln)
    except Exception: pass
    code=set()
    try:
        for tok in tokenize.generate_tokens(io.StringIO(src).readline):
            if tok.type in (tokenize.COMMENT, tokenize.NL, tokenize.NEWLINE, tokenize.INDENT, tokenize.DEDENT, tokenize.ENDMARKER): continue
            for ln in range(tok.start[0], tok.end[0]+1):
                if ln not in doc: code.add(ln)
    except Exception: pass
    stmt+=len(code)
print(f"files={len(files)} lines={tot} statement lines (non-comment, non-docstring token)={stmt} share={stmt/tot:.0%}")
PY

